
const WORDS=[{"id": 0, "w": "忙碌", "p": "mánglù", "t": "形容词", "m": "bận rộn", "coll": "忙碌的生活、整天忙碌", "s": "虽然每天的生活十分忙碌，她仍然坚持抽时间读书。"}, {"id": 1, "w": "被动", "p": "bèidòng", "t": "形容词", "m": "bị động", "coll": "被动接受、处于被动", "s": "学习时不能只是被动接受知识，还应该主动思考问题。"}, {"id": 2, "w": "奴隶", "p": "núlì", "t": "名词", "m": "nô lệ", "coll": "奴隶制度、成为奴隶", "s": "我们应该合理安排时间，不要让自己成为工作的奴隶。"}, {"id": 3, "w": "虚伪", "p": "xūwěi", "t": "形容词", "m": "giả dối, không thật", "coll": "虚伪的态度、十分虚伪", "s": "他表面上关心别人，实际上只考虑自己，让人觉得很虚伪。"}, {"id": 4, "w": "思想", "p": "sīxiǎng", "t": "名词", "m": "ý nghĩ, tư tưởng", "coll": "交流思想、思想观念", "s": "阅读不同类型的书籍，可以丰富我们的思想。"}, {"id": 5, "w": "反省", "p": "fǎnxǐng", "t": "动词", "m": "tự kiểm điểm", "coll": "反省自己、认真反省", "s": "遇到问题时，我们应该先反省自己的做法。"}, {"id": 6, "w": "据说", "p": "jùshuō", "t": "动词", "m": "nghe nói, nghe đồn", "coll": "据说如此、据说他来过", "s": "据说这位作家每天早上都会花两个小时散步。"}, {"id": 7, "w": "个性", "p": "gèxìng", "t": "名词", "m": "cá tính", "coll": "个性鲜明、尊重个性", "s": "每个孩子的个性都不同，老师应该尊重他们的特点。"}, {"id": 8, "w": "冒险", "p": "màoxiǎn", "t": "动词", "m": "mạo hiểm", "coll": "冒险旅行、不愿冒险", "s": "在没有做好准备的情况下，我们不应该冒险进入那片森林。"}, {"id": 9, "w": "丛林", "p": "cónglín", "t": "名词", "m": "rừng cây", "coll": "茂密的丛林、穿过丛林", "s": "探险队花了三天时间，才穿过这片茂密的丛林。"}, {"id": 10, "w": "文明", "p": "wénmíng", "t": "名词", "m": "nền văn minh", "coll": "古代文明、中华文明", "s": "这座博物馆向参观者展示了古代文明的发展过程。"}, {"id": 11, "w": "纪录", "p": "jìlù", "t": "动词 / 名词", "m": "ghi chép / tài liệu ghi tại chỗ", "coll": "纪录片、打破纪录", "s": "这部纪录片真实地展示了当地居民的日常生活。"}, {"id": 12, "w": "雇", "p": "gù", "t": "动词", "m": "thuê, mướn", "coll": "雇人帮忙、雇司机", "s": "由于店里的生意越来越好，老板决定再雇两名员工。"}, {"id": 13, "w": "来", "p": "lái", "t": "助词", "m": "khoảng (dùng sau số lượng)", "coll": "十来个人、二十来岁", "s": "参加这次讨论的只有十来个人，所以大家都有机会发言。"}, {"id": 14, "w": "批", "p": "pī", "t": "量词", "m": "tốp, nhóm, đợt", "coll": "一批学生、分批进入", "s": "新学期开始时，学校迎来了一批来自国外的学生。"}, {"id": 15, "w": "出色", "p": "chūsè", "t": "形容词", "m": "xuất sắc", "coll": "表现出色、出色完成", "s": "他凭借丰富的经验，出色地完成了这项艰巨的任务。"}, {"id": 16, "w": "健步如飞", "p": "jiànbù-rúfēi", "t": "成语", "m": "bước đi mạnh mẽ, thoăn thoắt", "coll": "老人健步如飞、走起路来健步如飞", "s": "这位老人虽然已经七十多岁，但走起路来仍然健步如飞。"}, {"id": 17, "w": "一连", "p": "yìlián", "t": "副词", "m": "liên tiếp", "coll": "一连三天、一连问了几次", "s": "为了完成这项工作，他一连三天都没有好好休息。"}, {"id": 18, "w": "耽误", "p": "dānwù", "t": "动词", "m": "làm chậm trễ, để lỡ", "coll": "耽误时间、耽误工作", "s": "路上发生了交通事故，耽误了我们不少时间。"}, {"id": 19, "w": "至于", "p": "zhìyú", "t": "介词", "m": "còn", "coll": "至于这个问题、至于以后", "s": "我已经决定下个月出发，至于具体日期，还要和大家商量。"}, {"id": 20, "w": "投资", "p": "tóuzī", "t": "动词", "m": "đầu tư", "coll": "投资项目、投资教育", "s": "这家公司计划在当地投资建设一家工厂。"}, {"id": 21, "w": "人物", "p": "rénwù", "t": "名词", "m": "nhân vật, người có vai vế", "coll": "历史人物、主要人物", "s": "这部小说的主要人物是一位热爱生活的年轻教师。"}, {"id": 22, "w": "得罪", "p": "dézuì", "t": "动词", "m": "làm phật lòng, xúc phạm", "coll": "得罪别人、无意中得罪", "s": "他担心说出自己的真实想法会得罪别人，所以一直没有开口。"}, {"id": 23, "w": "总算", "p": "zǒngsuàn", "t": "副词", "m": "cuối cùng, nói chung", "coll": "总算完成、总算明白", "s": "经过几次耐心的解释，他总算明白了这个道理。"}, {"id": 24, "w": "搞", "p": "gǎo", "t": "动词", "m": "làm, tạo ra", "coll": "搞活动、搞清楚", "s": "在开始行动之前，我们必须先把情况搞清楚。"}, {"id": 25, "w": "习俗", "p": "xísú", "t": "名词", "m": "tập tục", "coll": "当地习俗、传统习俗", "s": "去其他国家旅行以前，最好先了解一下当地的习俗。"}, {"id": 26, "w": "灵魂", "p": "línghún", "t": "名词", "m": "linh hồn, tâm hồn", "coll": "灵魂深处、作品的灵魂", "s": "在他看来，真诚的情感是一部作品的灵魂。"}, {"id": 27, "w": "疲劳", "p": "pílǎo", "t": "形容词", "m": "mệt mỏi, mệt nhọc", "coll": "感到疲劳、消除疲劳", "s": "连续工作几个小时以后，他开始感到疲劳。"}, {"id": 28, "w": "哲理", "p": "zhélǐ", "t": "名词", "m": "triết lý", "coll": "人生哲理、富有哲理", "s": "这个看似简单的故事，其实包含着深刻的人生哲理。"}, {"id": 29, "w": "提倡", "p": "tíchàng", "t": "动词", "m": "đề xướng, chủ trương", "coll": "提倡节约、积极提倡", "s": "学校一直提倡节约用水，鼓励学生从小事做起。"}, {"id": 30, "w": "步骤", "p": "bùzhòu", "t": "名词", "m": "bước", "coll": "操作步骤、按照步骤", "s": "使用这台机器之前，请先仔细阅读说明书上的操作步骤。"}, {"id": 31, "w": "闭关", "p": "bìguān", "t": "动词", "m": "bế quan, tịnh cư", "coll": "闭关修行、闭关读书", "s": "为了专心完成这本书，他决定暂时闭关，谢绝一切来访。"}, {"id": 32, "w": "一律", "p": "yílǜ", "t": "副词", "m": "nhất loạt, hết thảy", "coll": "一律禁止、一律平等", "s": "进入实验室以后，所有人一律不得饮食。"}, {"id": 33, "w": "寂寞", "p": "jìmò", "t": "形容词", "m": "cô đơn, cô độc", "coll": "感到寂寞、十分寂寞", "s": "刚到陌生的城市时，她因为没有朋友而感到寂寞。"}, {"id": 34, "w": "效率", "p": "xiàolǜ", "t": "名词", "m": "năng suất, hiệu suất", "coll": "提高效率、工作效率", "s": "合理安排每天的任务，能够有效提高工作效率。"}];
const CHUNKS={"0": ["虽然每天的生活十分忙碌，", "她仍然坚持", "抽时间读书。"], "1": ["学习时不能只是被动接受知识，", "还应该", "主动思考问题。"], "2": ["我们应该合理安排时间，", "不要让自己", "成为工作的奴隶。"], "3": ["他表面上关心别人，", "实际上只考虑自己，", "让人觉得很虚伪。"], "4": ["阅读不同类型的书籍，", "可以丰富", "我们的思想。"], "5": ["遇到问题时，", "我们应该先", "反省自己的做法。"], "6": ["据说这位作家", "每天早上", "都会花两个小时散步。"], "7": ["每个孩子的个性都不同，", "老师应该", "尊重他们的特点。"], "8": ["在没有做好准备的情况下，", "我们不应该", "冒险进入那片森林。"], "9": ["探险队", "花了三天时间，", "才穿过这片茂密的丛林。"], "10": ["这座博物馆", "向参观者展示了", "古代文明的发展过程。"], "11": ["这部纪录片", "真实地展示了", "当地居民的日常生活。"], "12": ["由于店里的生意越来越好，", "老板决定", "再雇两名员工。"], "13": ["参加这次讨论的", "只有十来个人，", "所以大家都有机会发言。"], "14": ["新学期开始时，", "学校迎来了", "一批来自国外的学生。"], "15": ["他凭借丰富的经验，", "出色地完成了", "这项艰巨的任务。"], "16": ["这位老人虽然已经七十多岁，", "但走起路来", "仍然健步如飞。"], "17": ["为了完成这项工作，", "他一连三天", "都没有好好休息。"], "18": ["路上发生了交通事故，", "耽误了", "我们不少时间。"], "19": ["我已经决定下个月出发，", "至于具体日期，", "还要和大家商量。"], "20": ["这家公司计划", "在当地", "投资建设一家工厂。"], "21": ["这部小说的主要人物", "是一位", "热爱生活的年轻教师。"], "22": ["他担心说出自己的真实想法", "会得罪别人，", "所以一直没有开口。"], "23": ["经过几次耐心的解释，", "他总算明白了", "这个道理。"], "24": ["在开始行动之前，", "我们必须先", "把情况搞清楚。"], "25": ["去其他国家旅行以前，", "最好先了解一下", "当地的习俗。"], "26": ["在他看来，", "真诚的情感", "是一部作品的灵魂。"], "27": ["连续工作几个小时以后，", "他开始", "感到疲劳。"], "28": ["这个看似简单的故事，", "其实包含着", "深刻的人生哲理。"], "29": ["学校一直提倡", "节约用水，", "鼓励学生从小事做起。"], "30": ["使用这台机器之前，", "请先仔细阅读", "说明书上的操作步骤。"], "31": ["为了专心完成这本书，", "他决定暂时闭关，", "谢绝一切来访。"], "32": ["进入实验室以后，", "所有人一律", "不得饮食。"], "33": ["刚到陌生的城市时，", "她因为没有朋友", "而感到寂寞。"], "34": ["合理安排每天的任务，", "能够有效提高", "工作效率。"]};
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai26-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===2?WORDS.length:g*10+10);
const groupOf=id=>Math.min(2,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/35 个词语。学完三组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),35)}<div class="ntc-progressgroups">${[0,1,2].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共35个词语，点击 ↗ 学习该词语',totalLearned()+'/35 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为三组：10、10、15个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===34;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<34){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:2,idx:14};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课35个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课35个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [2, 9, 30], "1": [2, 9, 30], "2": [9, 24, 27], "3": [2, 9, 30], "4": [2, 9, 30], "5": [2, 9, 30], "6": [2, 9, 30], "7": [2, 9, 30], "8": [2, 9, 30], "9": [2, 9, 30], "10": [2, 9, 30], "11": [2, 27, 30], "12": [2, 9, 30], "13": [2, 9, 30], "14": [3, 15, 33], "15": [2, 9, 30], "16": [2, 9, 30], "17": [2, 9, 30], "18": [2, 9, 30], "19": [2, 9, 30], "20": [2, 9, 30], "21": [2, 9, 30], "22": [2, 9, 30], "23": [2, 9, 30], "24": [2, 9, 30], "25": [2, 9, 30], "26": [2, 9, 30], "27": [2, 9, 30], "28": [2, 9, 30], "29": [2, 9, 30], "30": [2, 9, 30], "31": [2, 9, 30], "32": [2, 9, 30], "33": [2, 9, 30], "34": [2, 9, 30]};
const CONFUSABLE={};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id&&!(CONFUSABLE[id]||[]).includes(d.id)).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的35个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第26课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第26课学习进度','第26课 · 35个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 35</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第26课';$('ntc-bookmark').textContent=student?total+'/35 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第26课学习进度</div><div style="padding:0 10px">'+total+'/35 个已学词语'+meter(total,35)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"忙碌":"data:audio/mpeg;base64,","虽然每天的生活十分忙碌，她仍然坚持抽时间读书。":"data:audio/mpeg;base64,","被动":"data:audio/mpeg;base64,","学习时不能只是被动接受知识，还应该主动思考问题。":"data:audio/mpeg;base64,","奴隶":"data:audio/mpeg;base64,","我们应该合理安排时间，不要让自己成为工作的奴隶。":"data:audio/mpeg;base64,","虚伪":"data:audio/mpeg;base64,","他表面上关心别人，实际上只考虑自己，让人觉得很虚伪。":"data:audio/mpeg;base64,","思想":"data:audio/mpeg;base64,","阅读不同类型的书籍，可以丰富我们的思想。":"data:audio/mpeg;base64,","反省":"data:audio/mpeg;base64,","遇到问题时，我们应该先反省自己的做法。":"data:audio/mpeg;base64,","据说":"data:audio/mpeg;base64,","据说这位作家每天早上都会花两个小时散步。":"data:audio/mpeg;base64,","个性":"data:audio/mpeg;base64,","每个孩子的个性都不同，老师应该尊重他们的特点。":"data:audio/mpeg;base64,","冒险":"data:audio/mpeg;base64,","在没有做好准备的情况下，我们不应该冒险进入那片森林。":"data:audio/mpeg;base64,","丛林":"data:audio/mpeg;base64,","探险队花了三天时间，才穿过这片茂密的丛林。":"data:audio/mpeg;base64,","文明":"data:audio/mpeg;base64,","这座博物馆向参观者展示了古代文明的发展过程。":"data:audio/mpeg;base64,","纪录":"data:audio/mpeg;base64,","这部纪录片真实地展示了当地居民的日常生活。":"data:audio/mpeg;base64,","雇":"data:audio/mpeg;base64,","由于店里的生意越来越好，老板决定再雇两名员工。":"data:audio/mpeg;base64,","来":"data:audio/mpeg;base64,","参加这次讨论的只有十来个人，所以大家都有机会发言。":"data:audio/mpeg;base64,","批":"data:audio/mpeg;base64,","新学期开始时，学校迎来了一批来自国外的学生。":"data:audio/mpeg;base64,","出色":"data:audio/mpeg;base64,","他凭借丰富的经验，出色地完成了这项艰巨的任务。":"data:audio/mpeg;base64,","健步如飞":"data:audio/mpeg;base64,","这位老人虽然已经七十多岁，但走起路来仍然健步如飞。":"data:audio/mpeg;base64,","一连":"data:audio/mpeg;base64,","为了完成这项工作，他一连三天都没有好好休息。":"data:audio/mpeg;base64,","耽误":"data:audio/mpeg;base64,","路上发生了交通事故，耽误了我们不少时间。":"data:audio/mpeg;base64,","至于":"data:audio/mpeg;base64,","我已经决定下个月出发，至于具体日期，还要和大家商量。":"data:audio/mpeg;base64,","投资":"data:audio/mpeg;base64,","这家公司计划在当地投资建设一家工厂。":"data:audio/mpeg;base64,","人物":"data:audio/mpeg;base64,","这部小说的主要人物是一位热爱生活的年轻教师。":"data:audio/mpeg;base64,","得罪":"data:audio/mpeg;base64,","他担心说出自己的真实想法会得罪别人，所以一直没有开口。":"data:audio/mpeg;base64,","总算":"data:audio/mpeg;base64,","经过几次耐心的解释，他总算明白了这个道理。":"data:audio/mpeg;base64,","搞":"data:audio/mpeg;base64,","在开始行动之前，我们必须先把情况搞清楚。":"data:audio/mpeg;base64,","习俗":"data:audio/mpeg;base64,","去其他国家旅行以前，最好先了解一下当地的习俗。":"data:audio/mpeg;base64,","灵魂":"data:audio/mpeg;base64,","在他看来，真诚的情感是一部作品的灵魂。":"data:audio/mpeg;base64,","疲劳":"data:audio/mpeg;base64,","连续工作几个小时以后，他开始感到疲劳。":"data:audio/mpeg;base64,","哲理":"data:audio/mpeg;base64,","这个看似简单的故事，其实包含着深刻的人生哲理。":"data:audio/mpeg;base64,","提倡":"data:audio/mpeg;base64,","学校一直提倡节约用水，鼓励学生从小事做起。":"data:audio/mpeg;base64,","步骤":"data:audio/mpeg;base64,","使用这台机器之前，请先仔细阅读说明书上的操作步骤。":"data:audio/mpeg;base64,","闭关":"data:audio/mpeg;base64,","为了专心完成这本书，他决定暂时闭关，谢绝一切来访。":"data:audio/mpeg;base64,","一律":"data:audio/mpeg;base64,","进入实验室以后，所有人一律不得饮食。":"data:audio/mpeg;base64,","寂寞":"data:audio/mpeg;base64,","刚到陌生的城市时，她因为没有朋友而感到寂寞。":"data:audio/mpeg;base64,","效率":"data:audio/mpeg;base64,","合理安排每天的任务，能够有效提高工作效率。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai26-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai26_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai26-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=35)||!p.memory)throw Error();if(!confirm('恢复第26课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<35;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<3&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<35&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第26课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

